# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'

def task_func(ip_address):
    """
    Extracts and validates a public IP address from a JSON response.

    Args:
        ip_address: A string containing JSON with an IP address, or a raw IP string

    Returns:
        str: The valid public IP address, or 'Invalid IP address received'
    """
    # If input is a JSON string, try to parse it
    if isinstance(ip_address, str) and (ip_address.strip().startswith('{') or ip_address.strip().startswith('[')):
        try:
            data = json.loads(ip_address)
            # Search for IP in JSON values
            if isinstance(data, dict):
                for value in data.values():
                    if isinstance(value, str) and re.fullmatch(IP_REGEX, value):
                        ip_address = value
                        break
            elif isinstance(data, list):
                for item in data:
                    if isinstance(item, str) and re.fullmatch(IP_REGEX, item):
                        ip_address = item
                        break
        except json.JSONDecodeError:
            pass

    # Ensure we're working with a string
    if not isinstance(ip_address, str):
        return 'Invalid IP address received'

    # Extract IP using regex
    match = re.search(IP_REGEX, ip_address)
    if not match:
        return 'Invalid IP address received'

    ip_str = match.group()

    # Validate each octet is between 0 and 255
    octets = ip_str.split('.')
    if len(octets) != 4:
        return 'Invalid IP address received'

    for octet in octets:
        try:
            num = int(octet)
            if num < 0 or num > 255:
                return 'Invalid IP address received'
            # Check for leading zeros (except for 0 itself)
            if len(octet) > 1 and octet[0] == '0':
                return 'Invalid IP address received'
        except ValueError:
            return 'Invalid IP address received'

    # Exclude private and special-purpose IP ranges
    first_octet = int(octets[0])
    second_octet = int(octets[1])

    # Private IP ranges
    if first_octet == 10:
        return 'Invalid IP address received'
    if first_octet == 172 and 16 <= second_octet <= 31:
        return 'Invalid IP address received'
    if first_octet == 192 and second_octet == 168:
        return 'Invalid IP address received'
    # Loopback
    if first_octet == 127:
        return 'Invalid IP address received'
    # Link-local
    if first_octet == 169 and second_octet == 254:
        return 'Invalid IP address received'
    # Reserved (0.0.0.0/8)
    if first_octet == 0:
        return 'Invalid IP address received'
    # Multicast and reserved ranges
    if first_octet >= 224:
        return 'Invalid IP address received'

    return ip_str
