    """
    Extract recipient email addresses and names from JSON-formatted string,
    then send the names in an email.

    Args:
        input_data (str): JSON-formatted string containing email/name data
        smtp_server (str): SMTP server address
        smtp_port (int): SMTP server port
        email_address (str): Sender's email address
        email_password (str): Sender's email password
        smtp (smtplib.SMTP, optional): Pre-configured SMTP connection

    Returns:
        dict: Contains 'list' key with extracted names
    """
    try:
        # Parse the JSON input
        if input_data is None:
            return {"list": []}

        data = json.loads(input_data)

        # Extract names from the data
        names = []
        recipients = []

        # Handle different JSON structures
        if isinstance(data, list):
            for item in data:
                if isinstance(item, dict):
                    name = item.get('name', item.get('Name', ''))
                    email = item.get('email', item.get('Email', ''))
                    if name and email:
                        names.append(name)
                        recipients.append((name, email))
        elif isinstance(data, dict):
            # Handle single recipient or nested structures
            name = data.get('name', data.get('Name', ''))
            email = data.get('email', data.get('Email', ''))
            if name and email:
                names.append(name)
                recipients.append((name, email))
            else:
                # Check for 'recipients' or 'to' key containing list
                for key in ['recipients', 'to', 'contacts']:
                    if key in data and isinstance(data[key], list):
                        for item in data[key]:
                            if isinstance(item, dict):
                                name = item.get('name', item.get('Name', ''))
                                email = item.get('email', item.get('Email', ''))
                                if name and email:
                                    names.append(name)
                                    recipients.append((name, email))

        # If no names found, return empty list
        if not names:
            return {"list": []}

        # Prepare email content
        subject = "Extracted Names"
        body = "\n".join(names)
        message = f"Subject: {subject}\n\n{body}"

        # Send email
        try:
            if smtp is None:
                # Create new SMTP connection
                server = smtplib.SMTP(smtp_server, smtp_port)
                server.starttls()
                server.login(email_address, email_password)
            else:
                server = smtp

            server.sendmail(email_address, [email_address], message)

            if smtp is None:
                server.quit()

        except Exception as e:
            # If email sending fails, still return the names
            pass

        return {"list": names}

    except json.JSONDecodeError:
        return {"list": []}
    except Exception:
        return {"list": []}
