import collections
import json
import os

def task_func(directory_path: str) -> dict:
    """
    Counts the total appearances of all keys across all JSON files in the specified directory.

    Args:
        directory_path (str): Path to the directory containing JSON files.

    Returns:
        dict: A dictionary with keys from JSON files as keys and their total counts as values.
    """
    counter = collections.Counter()

    # Iterate through all files in the directory
    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            file_path = os.path.join(directory_path, filename)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    data = json.load(f)

                # If the JSON is a dictionary, count its keys
                if isinstance(data, dict):
                    counter.update(data.keys())
                # If the JSON is a list of dictionaries, count keys from each
                elif isinstance(data, list):
                    for item in data:
                        if isinstance(item, dict):
                            counter.update(item.keys())

            except (json.JSONDecodeError, IOError) as e:
                print(f"Error processing {filename}: {e}")
                continue

    return dict(counter)
