    key_path (list): List of keys to traverse through the JSON structure

    Returns:
    matplotlib.figure.Figure: A matplotlib figure showing a boxplot of the data values

    Raises:
    KeyError: If a specified key is not found
    ValueError: If no numeric data is found, or the data string is empty or corrupted
    """
    # Parse JSON string
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError as e:
        raise ValueError(f"Corrupted JSON data: {e}")

    # Traverse the key path
    current = data
    for key in key_path:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            raise KeyError(f"Key '{key}' not found in the JSON structure")

    # Extract numeric values
    values = []
    if isinstance(current, list):
        for item in current:
            try:
                num = float(item)
                values.append(num)
            except (ValueError, TypeError):
                # Try to extract from nested structures
                if isinstance(item, (list, dict)):
                    try:
                        values.extend(extract_numeric_values(item))
                    except (ValueError, TypeError):
                        continue
    elif isinstance(current, (int, float)):
        values = [float(current)]
    elif isinstance(current, dict):
        # Try to extract numeric values from dict values
        for v in current.values():
            try:
                num = float(v)
                values.append(num)
            except (ValueError, TypeError):
                continue
    elif isinstance(current, str):
        # Try to parse string as number or comma-separated numbers
        try:
            values = [float(current)]
        except ValueError:
            # Try comma-separated numbers
            try:
                values = [float(x.strip()) for x in current.split(',') if x.strip()]
            except ValueError:
                raise ValueError(f"No numeric data found in string: '{current}'")

    # Check if we have any numeric data
    if len(values) == 0:
        raise ValueError("No numeric data found at the specified path")

    # Create boxplot
    fig, ax = plt.subplots(figsize=(8, 6))

    # Create DataFrame for better visualization
    df = pd.DataFrame({'Values': values})

    # Create boxplot with seaborn for better aesthetics
    sns.boxplot(data=df, y='Values', ax=ax, color='lightblue', width=0.5)

    # Add individual data points (jittered)
    sns.stripplot(data=df, y='Values', ax=ax, color='darkblue', alpha=0.3, size=8, jitter=True)

    # Customize the plot
    ax.set_title(f'Boxplot of Data at Path: {" -> ".join(key_path)}', fontsize=14, fontweight='bold')
    ax.set_ylabel('Values', fontsize=12)
    ax.grid(True, alpha=0.3)

    # Add statistical annotations
    stats_text = f'n = {len(values)}\nMean = {np.mean(values):.2f}\nMedian = {np.median(values):.2f}\nSD = {np.std(values):.2f}'
    ax.text(0.95, 0.95, stats_text, transform=ax.transAxes, 
            verticalalignment='top', horizontalalignment='right',
            bbox=dict(boxstyle='round', facecolor='white', alpha=0.8),
            fontsize=10)

    plt.tight_layout()

    return fig

def extract_numeric_values(data):
    """Helper function to recursively extract numeric values from nested structures"""
    values = []
    if isinstance(data, (int, float)):
        values.append(float(data))
    elif isinstance(data, list):
        for item in data:
            values.extend(extract_numeric_values(item))
    elif isinstance(data, dict):
        for item in data.values():
            values.extend(extract_numeric_values(item))
    elif isinstance(data, str):
        try:
            values.append(float(data))
        except ValueError:
            pass
    return values
